import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/accessory/commands.md","filePath":"modules/accessory/commands.md","lastUpdated":0}`),a={name:`modules/accessory/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiAccessory 的命令在运行时注册，不在 <code>paper-plugin.yml</code> 里声明 <code>commands:</code> 段。</p><p>主命令 <code>/emakiaccessory</code>，别名 <code>/eaccessory</code>、<code>/eacc</code>。不带参数或子命令无法识别时打印帮助。</p><h2 id="子命令" tabindex="-1">子命令 <a class="header-anchor" href="#子命令" aria-label="Permalink to “子命令”">​</a></h2><table tabindex="0"><thead><tr><th>用法</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/eacc</code></td><td>无</td><td>打印帮助。</td></tr><tr><td><code>/eacc open [页]</code></td><td><code>emakiaccessory.use</code></td><td>打开自己的饰品栏；省略页时打开当前启用页。</td></tr><tr><td><code>/eacc list</code></td><td><code>emakiaccessory.use</code></td><td>列出当前启用页的饰品槽与占用情况。</td></tr><tr><td><code>/eacc pages</code></td><td><code>emakiaccessory.use</code></td><td>列出所有饰品页、当前启用页与各页占用数量。</td></tr><tr><td><code>/eacc retrieve &lt;页&gt;</code></td><td><code>emakiaccessory.use</code></td><td>取回指定页中不再被声明的孤儿槽饰品。</td></tr><tr><td><code>/eacc reload</code></td><td><code>emakiaccessory.reload</code></td><td>重载配置、部位、饰品页与套装。</td></tr><tr><td><code>/eacc debug</code></td><td><code>emakiaccessory.debug</code></td><td>调试开关。</td></tr><tr><td><code>/eacc admin &lt;...&gt;</code></td><td><code>emakiaccessory.admin</code></td><td>管理指令，见下文。</td></tr></tbody></table><p><code>open</code>、<code>list</code>、<code>pages</code>、<code>retrieve</code> 只能由玩家执行。玩家数据尚未加载完成时，这些命令会提示稍后再试而不是返回空结果。</p><h2 id="管理指令" tabindex="-1">管理指令 <a class="header-anchor" href="#管理指令" aria-label="Permalink to “管理指令”">​</a></h2><table tabindex="0"><thead><tr><th>用法</th><th>额外权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/eacc admin view &lt;玩家&gt;</code></td><td>无</td><td>查看饰品（只读）。</td></tr><tr><td><code>/eacc admin edit &lt;玩家&gt;</code></td><td><code>emakiaccessory.admin.edit</code></td><td>编辑饰品，<strong>仅在线玩家</strong>。</td></tr><tr><td><code>/eacc admin clear &lt;玩家&gt;</code></td><td>无</td><td>清空饰品，<strong>不可撤销</strong>，会记入日志。</td></tr><tr><td><code>/eacc admin save</code></td><td>无</td><td>立刻保存所有饰品数据。</td></tr></tbody></table><p>四个管理子命令都先要求 <code>emakiaccessory.admin</code>。<code>edit</code> 在此之上额外要求 <code>emakiaccessory.admin.edit</code>——把「能看」与「能改」分成两个节点，便于只给客服查看权而不给修改权。</p><p><code>view</code> 支持离线玩家：目标不在缓存中时会异步读档后以只读窗口打开。<code>edit</code> 只允许在线目标，因为可写窗口需要一个活的数据会话。</p><h2 id="页面与取回" tabindex="-1">页面与取回 <a class="header-anchor" href="#页面与取回" aria-label="Permalink to “页面与取回”">​</a></h2><p>多页模型下，命令的作用范围要分清：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用范围</th></tr></thead><tbody><tr><td><code>open [页]</code></td><td>打开指定页的界面；没有该页权限时打不开</td></tr><tr><td><code>list</code></td><td>只列出<strong>当前启用页</strong>的槽位</td></tr><tr><td><code>pages</code></td><td>列出所有页，并标出启用页与无权限页</td></tr><tr><td><code>retrieve &lt;页&gt;</code></td><td>只取回<strong>该页</strong>孤儿槽里的饰品</td></tr></tbody></table><p>孤儿槽是「该页数据里存在、但该页 <code>parts</code> 已不再声明」的槽位。取回是单向操作：取出后不能再放回孤儿槽。<code>retrieve</code> 需要取得该玩家的写入租约，租约被占用时会提示稍后再试。</p><p>玩家失去某页权限时，该页数据不会被清除，也不会自动切换启用页；该页打不开、其饰品停止生效，玩家可用 <code>retrieve</code> 自行取回。</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><p><code>paper-plugin.yml</code> 声明的权限及默认值：</p><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>emakiaccessory.use</code></td><td><code>true</code></td><td>打开自己的饰品栏、列出槽位与页、取回孤儿槽。</td></tr><tr><td><code>emakiaccessory.reload</code></td><td><code>op</code></td><td>重载配置。</td></tr><tr><td><code>emakiaccessory.debug</code></td><td><code>op</code></td><td>调试开关。</td></tr><tr><td><code>emakiaccessory.admin</code></td><td><code>op</code></td><td>进入管理指令。</td></tr><tr><td><code>emakiaccessory.admin.edit</code></td><td><code>op</code></td><td>编辑他人饰品。</td></tr><tr><td><code>emakiaccessory.page.secondary</code></td><td><code>op</code></td><td>默认副饰品页 <code>secondary</code> 的页权限示例。</td></tr></tbody></table><p>本模块<strong>没有</strong>按槽位数量分级的权限。饰品槽数量完全由 <code>parts.yml</code> 的部位与 <code>count</code> 决定，不受权限影响。</p><p>页权限与命令权限是两回事：<code>pages/*.yml</code> 的 <code>permission</code> 只决定某一页能否打开与生效，逐字使用该权限串，不参与命令入口判定。默认资源只为 <code>secondary</code> 页声明了权限串，自建页需要自行选择权限名。</p><h2 id="写入租约" tabindex="-1">写入租约 <a class="header-anchor" href="#写入租约" aria-label="Permalink to “写入租约”">​</a></h2><p>同一个玩家的饰品数据同时只允许一个可写窗口。租约是建议性的：第二个观察者获取租约失败后转为只读窗口，仍然能看，但所有修改会被拒绝。</p><p>租约在提交路径上检查而不是渲染时检查，因此失去租约的观察者仍能看完当前画面，只是改不动。</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};